    public void parseFragmentTest() {
        XmlTreeBuilder xmlTreeBuilder = new XmlTreeBuilder();
        List<Node> nodes = xmlTreeBuilder.parseFragment("<test>content</test>", "http://test.com", Parser.xmlParser());
        Assert.assertNotNull(nodes);
    }
